"""Reviewed expansion of thin regions; no network/model calls in daily builds.

Each record denotes a named collaboration, service platform or programme, not
a news mention. Facts are paraphrased from the cited official page or indexed
official excerpt; constraints and transfer lessons are editorial interpretation.
"""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DATE = "2026-10-09"
CASES, SOURCES, PROFILES = [], [], []
SECTORS = json.loads((ROOT/'config/open_innovation_coverage.json').read_text(encoding='utf-8'))['sector_taxonomy']

def bi(value):
    zh, en = value.split('|', 1)
    return {'zh':zh, 'en':en}

def add(key, country, province, city, title, model, sector, url, publisher,
        language, summary, actors, mechanism, observed, constraints, transfer,
        *, factors=('knowledge','market'), institutions=('research',), period=None):
    existing = next((s for s in SOURCES if s['url']==url), None)
    sid = existing['id'] if existing else 's_expansion_'+key
    if not existing:
        SOURCES.append(dict(id=sid,url=url,title=bi(title)['zh'],publisher=publisher,
            language=language,published_date=None,reviewed_at=DATE,
            access='public_metadata_and_paraphrase',source_role='primary',
            review_basis='official_page_text_or_indexed_official_excerpt'))
    CASES.append(dict(id='oi_'+key,title=bi(title),countries=[country],scope='national',
        sector=SECTORS[sector],sector_key=sector,aliases=list(bi(title).values()),
        challenges=['factor','adaptation'],
        modes=['testbed' if model=='pilot' else 'incubation' if model in ('venture','capacity') else 'translation'],
        institutions=list(institutions),factors=list(factors),
        start_year=period[0] if period else None,end_year=period[1] if period else None,
        review_status='reviewed',
        **{k:bi(v) for k,v in zip(('summary','actors','mechanism','observed','constraints','transfer'),
                                  (summary,actors,mechanism,observed,constraints,transfer))},
        evidence=[dict(source_id=sid,supports=['summary','actors','mechanism','observed'])],
        research_annotation=dict(primary_model=model,country=country,province=province,city=city,
            grain='platform',cohort='expansion_review',basis='manual_source_review',reviewed_at=DATE,
            interpretation_fields=['constraints','transfer','primary_model'])))

