def profile(key, title, model, keys, mechanism, conditions, factors, government, boundary, province=None):
    row=dict(id=key,name=bi(title),archetype=model,case_ids=['oi_'+k for k in keys],
        **{k:bi(v) for k,v in zip(('mechanism','conditions','factors','government','boundary'),
                                  (mechanism,conditions,factors,government,boundary))})
    if province: row['province']=province
    PROFILES.append(row)

