def main():
    from collections import Counter
    payload=dict(schema_version='1.0',reviewed_at=DATE,cases=CASES,sources=SOURCES,
        sector_taxonomy=SECTORS,model_profiles=PROFILES,
        provenance=dict(expansion_review=dict(reviewed_at=DATE,
            selection='Named independent programmes, collaborations or platforms from official sources; thin regions prioritised.',
            limitations='Purposive evidence sample, not a global census or innovation-performance ranking. Historical sources are identified in observed/constraints; inaccessible pages may be supported by indexed official excerpts.',
            interpretation_fields=['constraints','transfer','primary_model','model_profiles'])))
    target=ROOT/'config/open_innovation_expansion.json'
    target.write_text(json.dumps(payload,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(json.dumps(dict(cases=len(CASES),sources=len(SOURCES),profiles=len(PROFILES),
        countries=dict(Counter(c['countries'][0] for c in CASES))),ensure_ascii=False))

if __name__=='__main__': main()
